//! Parity between the join of kept takes in `voxr_narrate` and the
//! JavaScript `shapeTake`, heat reading and join it ports.
//!
//! The fixture (`tests/fixtures/narration_join_oracle.json`) is checked in
//! and was generated by `tests/tools/narration_oracle/take_join.mjs`, which
//! runs a patched copy of the skill's own `voxcpm` to the end with the model
//! call and the judge stubbed: each take the judge meets is a synthetic
//! take, one tone per sentence built as `common::signals` builds it, with
//! its sentence words heard evenly over each tone. Each case here replays
//! the same script and takes through [`TakeLoop::best_takes`], shapes each
//! kept take ([`shape_take`]) and joins them, and compares the parts as
//! finally spoken, each shaped take by hash and spans, the joined samples
//! and the written file by hash, the duration, the phrases, the checks and
//! the problems.

use std::path::Path;

use serde::Deserialize;
use voxr_narrate::{
    Chunk, ChunkOptions, CloneReference, Error, HeardCheck, HeardWord, JOIN_RATE, JudgedTake,
    PickSetup, Result, SpeakRequest, SpeechEngine, StrayPause, Take, TakeJudge, TakeLoop, TakeSpec,
    TakeStore, Verdict, VoiceSource, chunks, js_json, median_pitch, pcm16_round_trip, pcm16_wav,
    shape_take,
};

mod common;
use common::signals;
use common::take_files::{OpJson, render_json};
use common::{assert_oracle_current, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_join_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_join.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    anchor: Vec<OpJson>,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    script: String,
    voice_median: String,
    takes: Vec<TakeJson>,
    parts: Vec<String>,
    shaped: Vec<Shaped>,
    joined: String,
    file: String,
    duration: String,
    phrases: String,
    checks: String,
    problems: Vec<String>,
}

/// A take the judge returned, and its verdict.
#[derive(Debug, Deserialize)]
struct TakeJson {
    text: String,
    n: usize,
    ops: Vec<OpJson>,
    words: Vec<HeardWord>,
    ok: bool,
    badness: f64,
    why: String,
    heard: String,
    doubt: Vec<String>,
    pauses: Vec<PauseJson>,
    clicks: Vec<f64>,
    input: String,
}

#[derive(Debug, Deserialize)]
struct PauseJson {
    after: String,
    before: String,
    gap: f64,
}

#[derive(Debug, Deserialize)]
struct Shaped {
    samples: String,
    length: usize,
    spans: String,
}

/// Speaks an empty take for every request.
struct Engine;

impl SpeechEngine for Engine {
    type Reference = ();

    fn speak(&mut self, _request: &SpeakRequest<'_, ()>) -> Result<Take> {
        Ok(Take {
            samples: Vec::new(),
            rate: JOIN_RATE,
        })
    }
}

/// Judges each take by the case's table, as the oracle's stub judge does:
/// the synthetic take read back from its 16-bit file, its heard words and
/// its verdict.
struct Judge<'a> {
    takes: &'a [TakeJson],
}

impl TakeJudge for Judge<'_> {
    type Verdict = JudgedTake;

    fn judge(&mut self, spec: &TakeSpec, _take: &Take) -> Result<JudgedTake> {
        let t = self
            .takes
            .iter()
            .find(|t| t.text == spec.text)
            .ok_or_else(|| Error::DataError {
                reason: format!("no take for {:?} in the fixture", spec.text),
            })?;
        Ok(JudgedTake {
            heard: HeardCheck {
                check: Verdict {
                    ok: t.ok,
                    extra: Vec::new(),
                    missing: Vec::new(),
                    unsure: Some(Vec::new()),
                    why: t.why.clone(),
                    badness: Some(t.badness),
                },
                doubt: t.doubt.clone(),
                words: t.words.clone(),
                pauses: t
                    .pauses
                    .iter()
                    .map(|p| StrayPause {
                        after: p.after.clone(),
                        before: p.before.clone(),
                        gap: p.gap,
                    })
                    .collect(),
                heard: t.heard.clone(),
            },
            take: Take {
                samples: pcm16_round_trip(&render_json(t.n, &t.ops)),
                rate: JOIN_RATE,
            },
            seed: spec.seed,
            thumps: 0,
            fixed: 0,
            clicks: t.clicks.clone(),
        })
    }
}

/// Holds takes by `(text, seed, delivery)`.
#[derive(Default)]
struct Store {
    held: Vec<(String, f64, Option<String>)>,
}

impl Store {
    fn key(spec: &TakeSpec) -> (String, f64, Option<String>) {
        (spec.text.clone(), spec.seed, spec.delivery.clone())
    }
}

impl TakeStore for Store {
    fn has(&mut self, spec: &TakeSpec) -> bool {
        self.held.contains(&Self::key(spec))
    }

    fn load(&mut self, spec: &TakeSpec) -> Result<Take> {
        if !self.has(spec) {
            return Err(Error::DataError {
                reason: format!("no take of {:?} at seed {}", spec.text, spec.seed),
            });
        }
        Ok(Take {
            samples: Vec::new(),
            rate: JOIN_RATE,
        })
    }

    fn save(&mut self, spec: &TakeSpec, _take: &Take) -> Result<()> {
        self.held.push(Self::key(spec));
        Ok(())
    }
}

fn run(case: &Case, voice_median: f64) -> Result<()> {
    let name = &case.name;
    assert_eq!(
        voice_median,
        num(&case.voice_median),
        "voice median, case {name}"
    );
    for t in &case.takes {
        let input = signals::fnv1a(&pcm16_round_trip(&render_json(t.n, &t.ops)));
        assert_eq!(input, t.input, "input of take {:?}, case {name}", t.text);
    }
    let units: Vec<Chunk> = chunks(
        &case.script,
        ChunkOptions {
            lines: false,
            max: 700,
            whole: true,
        },
    )?;
    let chosen = Default::default();
    let mut engine = Engine;
    let mut judge = Judge { takes: &case.takes };
    let mut store = Store::default();
    let mut take_loop = TakeLoop {
        setup: PickSetup {
            seed: 7.0,
            chosen: &chosen,
            style: None,
            voice: VoiceSource::Clone {
                reference: CloneReference::Handle(&()),
                transcript: None,
            },
            cfg: 1.6,
            steps: 16,
        },
        engine: &mut engine,
        judge: &mut judge,
        store: &mut store,
    };
    let mut random = || -> f64 { panic!("case {name} re-rolls no part") };
    let best = take_loop.best_takes(units, &[], &mut random)?;

    let parts: Vec<&str> = best.parts.iter().map(|p| p.text.as_str()).collect();
    assert_eq!(parts, case.parts, "parts, case {name}");
    assert_eq!(
        best.best.len(),
        case.shaped.len(),
        "shaped count, case {name}"
    );
    for (i, ((part, b), want)) in best
        .parts
        .iter()
        .zip(&best.best)
        .zip(&case.shaped)
        .enumerate()
    {
        let v = &b.verdict;
        let shaped = shape_take(&v.take.samples, &v.heard.words, &part.sentences)?;
        assert_eq!(
            shaped.audio.len(),
            want.length,
            "shaped[{i}] length, case {name}"
        );
        assert_eq!(
            signals::fnv1a(&shaped.audio),
            want.samples,
            "shaped[{i}] samples, case {name}"
        );
        assert_eq!(
            js_json(&shaped.spans)?,
            want.spans,
            "shaped[{i}] spans, case {name}"
        );
    }

    let track = best.join(voice_median)?;
    assert_eq!(
        signals::fnv1a(&track.samples),
        case.joined,
        "joined, case {name}"
    );
    assert_eq!(
        signals::fnv1a_bytes(&pcm16_wav(&track.samples, JOIN_RATE)?),
        case.file,
        "written file, case {name}"
    );
    assert_eq!(track.duration, num(&case.duration), "duration, case {name}");
    assert_eq!(
        js_json(&track.phrases)?,
        case.phrases,
        "phrases, case {name}"
    );
    assert_eq!(
        js_json(&best.checks(&track)?)?,
        case.checks,
        "checks, case {name}"
    );
    assert_eq!(best.problems(), case.problems, "problems, case {name}");
    Ok(())
}

#[test]
fn matches_javascript_on_every_case() -> Result<()> {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    let anchor = render_json(JOIN_RATE as usize, &fixture.anchor);
    let voice_median = median_pitch(&pcm16_round_trip(&anchor));
    for case in &fixture.cases {
        run(case, voice_median)?;
    }
    Ok(())
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
